package sohal.lld.snakeladder;import sohal.lld.snakeladder.board.Board;import sohal.lld.snakeladder.board.builder.BoardBuilder;import sohal.lld.snakeladder.dice.Dice;import sohal.lld.snakeladder.entity.Entity;import sohal.lld.snakeladder.entity.factory.LadderFactory;import sohal.lld.snakeladder.entity.factory.SnakeFactory;import sohal.lld.snakeladder.player.Player;import java.util.LinkedList;import java.util.Map;import java.util.Queue;public class Game {    Dice dice;    Board board;    GameStatus gameStatus;    Queue<Player> players;    Player winner;    public static final int SIZE = 100;    public static final int TARGET = SIZE - 1;    public Game() {        this.board = BoardBuilder.newBuilder()                .withSize(SIZE)                .withSnakes(12)                .withLadders(12)                .withSnakeFactory(new SnakeFactory())                .withLadderFactory(new LadderFactory())                .build();        this.dice = new Dice();        Player player1  = new Player( "Jack", 0);        Player player2  = new Player( "Ada", 0);        Queue<Player> playerQueue = new LinkedList<Player>();        playerQueue.add(player1);        playerQueue.add(player2);        gameStatus = GameStatus.NOT_STARTED;        players = playerQueue;    }    public void takeTurn(Player player) {        int roll = dice.roll();        int playerPos = player.getPosition();        System.out.println("Player " + player.getName() + " is taking turn");        System.out.println("Player " + player.getName() + " rolls " + roll);        int finalPos = getFinalPosition(player, playerPos, roll);        player.setPosition(finalPos);        if(finalPos == TARGET) {            winner = player;            System.out.println("Player " + player.getName() + " won the game! Hurray!!!");            gameStatus = GameStatus.FINISHED;        };        try {            Thread.sleep(200);        } catch (InterruptedException e) {            throw new RuntimeException(e);        }    }    public void play() {        this.gameStatus = GameStatus.PLAYING;        System.out.println("Game Started");        while(gameStatus == GameStatus.PLAYING) {            Player currentPlayer = players.poll();            takeTurn(currentPlayer);            players.add(currentPlayer);        }    }    private int getFinalPosition(Player player, int currPos, int roll) {        int tempPos =  currPos + roll;        int finalPos = board.getFinalPosition(tempPos);        if(finalPos == -1) {            System.out.printf("\n %s Can't move to ahead! Try again.\n", player.getName());            return currPos;        }        else if(finalPos < currPos) {            System.out.printf("\nOh no! %s was bitten by a snake 🐍 at %d and slid down to %d.\n", player.getName(), tempPos, finalPos);        } else if(finalPos > (currPos + 6)) {            System.out.printf("\nWow! %s found a ladder 🪜 at %d and climbed to %d.\n", player.getName(), tempPos, finalPos);        } else {            System.out.printf("%s moved from %d to %d.\n", player.getName(), tempPos, finalPos);        }        return finalPos;    }}